insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('accounting-equation','Assets, liabilities and the accounting equation','accounting','Accounting','Beginner',8,'Build your understanding of a balance sheet from the ground up.',ARRAY['How does taking a loan affect both sides of the accounting equation?','Why is a credit sale not immediately cash?']::text[],'[{"body":"The equation is Assets = Liabilities + Owner''s Equity. Assets are controlled economic resources; liabilities are obligations; equity is the residual interest after deducting liabilities.","example":"A shop with KSh 80,000 in assets and KSh 30,000 in payables has KSh 50,000 owner equity.","heading":"Everything must balance"},{"body":"Double-entry accounting ensures the equation remains balanced. Taking a loan increases both cash and a loan liability. Buying inventory for cash exchanges one asset for another.","example":"Borrowing KSh 20,000 increases both cash and the amount owed to the lender by KSh 20,000.","heading":"Transactions have two effects"},{"body":"Revenue can be recorded when earned, before a customer pays. That creates a receivable asset. When the customer pays, receivables decrease and cash increases.","example":"Selling goods on 30-day credit creates revenue and a receivable; collecting the debt is not another sale.","heading":"Profit can increase without cash"}]'::jsonb,'[{"answer":"The equation is Assets = Liabilities + Owner''s Equity. Assets are controlled economic resources; liabilities are obligations; equity is the residual interest after deducting liabilities.","question":"How does taking a loan affect both sides of the accounting equation?"},{"answer":"Double-entry accounting ensures the equation remains balanced. Taking a loan increases both cash and a loan liability. Buying inventory for cash exchanges one asset for another.","question":"Why is a credit sale not immediately cash?"}]'::jsonb,'calculator','indigo',true)
