insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('basic-probability','Probability without the confusion','statistics','Mathematics & Statistics','Beginner',8,'Reason with uncertainty, complements and independent events.',ARRAY['What does probability 0.3 mean?','Why must independence be justified before multiplying probabilities?']::text[],'[{"body":"Probabilities range from 0 to 1. A probability of 0.7 is not a guarantee of success on a single trial; across many comparable trials it represents a roughly 70% long-run frequency.","example":"A 70% forecast of rain does not mean rain must occur.","heading":"Probability describes chance"},{"body":"P(not A) = 1 − P(A). Sometimes calculating the chance of all failures is easier than directly counting the chance of at least one success.","example":"If independent attempts each succeed with probability 0.2, the chance of at least one success in three attempts is 1 − 0.8³ = 0.488.","heading":"Use the complement"},{"body":"Independent events do not change one another''s chances. Shared causes can make outcomes dependent even if they occur on different days.","example":"Shop sales on two rainy days may depend on common weather and promotions.","heading":"Do not assume independence"}]'::jsonb,'[{"answer":"Probabilities range from 0 to 1. A probability of 0.7 is not a guarantee of success on a single trial; across many comparable trials it represents a roughly 70% long-run frequency.","question":"What does probability 0.3 mean?"},{"answer":"P(not A) = 1 − P(A). Sometimes calculating the chance of all failures is easier than directly counting the chance of at least one success.","question":"Why must independence be justified before multiplying probabilities?"}]'::jsonb,'calculator','indigo',true)
