insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('business-idea-validation','Validate your business idea before building','entrepreneurship','Entrepreneurship','Beginner',8,'Test problems and demand with interviews and a measurable pilot.',ARRAY['Why are behavioural interviews stronger than leading questions?','What should a pilot measure?']::text[],'[{"body":"An idea is not evidence of market demand. First identify a specific group facing a recurring problem and the alternatives they already use.","example":"Instead of ''Would you use an app for studying?'', ask ''How did you revise for your last difficult test?''","heading":"Start with a problem hypothesis"},{"body":"Ask about actual attempts, costs, frustrations and outcomes. Hypothetical enthusiasm or compliments do not prove a customer will use or pay for something.","example":"A student returning for three independent study sessions is stronger evidence than ten people calling your mockup beautiful.","heading":"Study past behaviour"},{"body":"Select a narrow audience, one important task and an observable success metric. Watch where people become confused, fail or abandon the workflow; fix that before expanding.","example":"Invite ten students to import notes and complete a short practice session. Measure completion without assistance.","heading":"Pilot one repeatable task"}]'::jsonb,'[{"answer":"An idea is not evidence of market demand. First identify a specific group facing a recurring problem and the alternatives they already use.","question":"Why are behavioural interviews stronger than leading questions?"},{"answer":"Ask about actual attempts, costs, frustrations and outcomes. Hypothetical enthusiasm or compliments do not prove a customer will use or pay for something.","question":"What should a pilot measure?"}]'::jsonb,'briefcase','indigo',true)
