insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('cash-flow-profit','Why profitable businesses still run out of cash','accounting','Accounting','Beginner',8,'Understand timing, credit sales, inventory and weekly cash forecasts.',ARRAY['Why can accounting profit rise as cash falls?','What information belongs in a cash-flow forecast?']::text[],'[{"body":"Profit is the difference between revenue earned and expenses incurred over a period. Cash flow is the actual money received and paid. The two can diverge sharply when customers buy on credit.","example":"A business makes a KSh 15,000 accounting profit on a credit sale but receives no cash that week.","heading":"Profit and cash are different measurements"},{"body":"Stock, unpaid customer invoices and supplier payables all affect available working capital. More inventory can increase reported assets while draining spendable cash.","example":"A shop orders slow-moving stock and then struggles to pay rent despite apparently healthy sales.","heading":"Working capital ties up money"},{"body":"List expected customer collections separately from invoices issued. Plan supplier payments, rent, wages, instalments and taxes on a weekly schedule; update assumptions when customers pay late.","example":"Build a rolling 13-week cash forecast and mark uncertain receipts so they are not mistaken for committed funds.","heading":"Forecast cash receipts and bills"}]'::jsonb,'[{"answer":"Profit is the difference between revenue earned and expenses incurred over a period. Cash flow is the actual money received and paid. The two can diverge sharply when customers buy on credit.","question":"Why can accounting profit rise as cash falls?"},{"answer":"Stock, unpaid customer invoices and supplier payables all affect available working capital. More inventory can increase reported assets while draining spendable cash.","question":"What information belongs in a cash-flow forecast?"}]'::jsonb,'chart','indigo',true)
