insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('critical-reading','Read and evaluate claims like a researcher','education','Study Skills','Beginner',8,'Find the main argument, judge the evidence and practise recall.',ARRAY['How can an accurate statistic still be misleading?','Why does recall reveal understanding better than passive highlighting?']::text[],'[{"body":"Separate what the author claims from the observations presented as evidence. Ask what assumptions connect them and whether plausible explanations are missing.","example":"A report claims tutoring improved scores. Ask how scores were compared and whether the groups were alike before tutoring.","heading":"Identify claim and support"},{"body":"Look for authorship, publication timing, original data, sample selection and definitions. A small sample or selective chart may not justify a broad conclusion.","example":"A study at one school should not be generalised automatically to every school.","heading":"Check context and provenance"},{"body":"Close the source and reconstruct the main ideas from memory, then check and correct gaps. Recognition during rereading often feels like learning without demonstrating recall.","example":"After finishing a chapter, write three ideas and two unanswered questions before opening it again.","heading":"Use retrieval to test comprehension"}]'::jsonb,'[{"answer":"Separate what the author claims from the observations presented as evidence. Ask what assumptions connect them and whether plausible explanations are missing.","question":"How can an accurate statistic still be misleading?"},{"answer":"Look for authorship, publication timing, original data, sample selection and definitions. A small sample or selective chart may not justify a broad conclusion.","question":"Why does recall reveal understanding better than passive highlighting?"}]'::jsonb,'books','indigo',true)
