insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('fair-experiments','How to design a fair experiment','biology','Natural Sciences','Beginner',8,'Work with variables, control groups and evidence rather than assumptions.',ARRAY['What is a confounding variable?','Why do repeated trials strengthen a claim?']::text[],'[{"body":"The independent variable is what you change. The dependent variable is what you measure. State precisely how both will be defined.","example":"To test light and bean growth, vary hours of light and measure plant height after two weeks.","heading":"Make the question testable"},{"body":"Control groups and standardised conditions help isolate the effect of the independent variable. Random allocation reduces systematic group differences.","example":"If the brighter plants receive more water, the result cannot isolate the effect of light.","heading":"Control alternative causes"},{"body":"Sample size, measurement errors and confounders all affect confidence. Correlation alone does not prove causation, and findings should be reproducible.","example":"Comparing only one plant per group is weak evidence; use repeated samples and report the measurement spread.","heading":"Interpret variation honestly"}]'::jsonb,'[{"answer":"The independent variable is what you change. The dependent variable is what you measure. State precisely how both will be defined.","question":"What is a confounding variable?"},{"answer":"Control groups and standardised conditions help isolate the effect of the independent variable. Random allocation reduces systematic group differences.","question":"Why do repeated trials strengthen a claim?"}]'::jsonb,'science','indigo',true)
