insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('javascript-ui-state','JavaScript state, events and user interactions','programming','Programming','Beginner',8,'Learn to make interfaces respond predictably.',ARRAY['How does duplicate derived state create bugs?','What should happen to an older search request after a new one?']::text[],'[{"body":"State holds values such as the selected tab, entered answer or current filter. Derived values should usually be calculated from existing state instead of kept in separate counters.","example":"Store which tasks are complete; compute ''3 of 5 completed'' from the tasks rather than separately updating a total.","heading":"State remembers what changes"},{"body":"Click, input and submit handlers connect user actions to application logic. Keep each action focused, and make loading and error feedback visible.","example":"Clicking a flashcard can toggle answer visibility. Moving to the next card should reset the flipped state.","heading":"Events capture user intent"},{"body":"Requests can finish in a different order from when they started. Ignore stale search results and account for errors, cancellations and empty responses.","example":"A slow result for ''eco'' must not overwrite the newer results for ''economics''.","heading":"Async results arrive in unpredictable order"}]'::jsonb,'[{"answer":"State holds values such as the selected tab, entered answer or current filter. Derived values should usually be calculated from existing state instead of kept in separate counters.","question":"How does duplicate derived state create bugs?"},{"answer":"Click, input and submit handlers connect user actions to application logic. Keep each action focused, and make loading and error feedback visible.","question":"What should happen to an older search request after a new one?"}]'::jsonb,'code','indigo',true)
