insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('leadership-management','Leadership and management are not the same','management','Management','Beginner',8,'Understand direction-setting, organisation, feedback and team performance.',ARRAY['How do management and leadership complement each other?','What makes feedback actionable?']::text[],'[{"body":"Management turns objectives into organised action through planning, resources and controls. Leadership helps people understand direction, commit to it and adapt when conditions change.","example":"A manager schedules shifts; a leader explains why accurate service matters and builds ownership.","heading":"Two complementary responsibilities"},{"body":"A beginner handling a safety-critical task often needs precise guidance. An experienced specialist may thrive with autonomy. Effective leaders change their approach based on ability, motivation and risk.","example":"Giving a new worker zero instructions can be just as damaging as micromanaging an experienced one.","heading":"Match support to the situation"},{"body":"Good feedback describes an observable action, explains the effect and suggests an achievable next step. Vague praise or blame does not help someone improve.","example":"Instead of ''be professional'', say ''send the meeting recap the same day so decisions and owners are clear''.","heading":"Useful feedback is concrete"}]'::jsonb,'[{"answer":"Management turns objectives into organised action through planning, resources and controls. Leadership helps people understand direction, commit to it and adapt when conditions change.","question":"How do management and leadership complement each other?"},{"answer":"A beginner handling a safety-critical task often needs precise guidance. An experienced specialist may thrive with autonomy. Effective leaders change their approach based on ability, motivation and risk.","question":"What makes feedback actionable?"}]'::jsonb,'briefcase','indigo',true)
