insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('market-segmentation','Market segmentation: choose who you serve','marketing','Marketing','Beginner',8,'Focus your message, positioning and customer experience.',ARRAY['How do you know a segment is useful?','Why is a narrow positioning statement often stronger?']::text[],'[{"body":"Segments group customers with similar needs or behaviour. Useful segments can be described, reached and served economically. Segment by urgency, context, needs and buying behaviour rather than demographics alone.","example":"A cake business may serve birthdays, office events and weddings. Each group differs in budget, delivery planning and presentation needs.","heading":"Not everyone wants the same thing"},{"body":"Good positioning states the difference that matters to a particular customer, supported by evidence. Trying to be the fastest, cheapest and highest quality to everyone weakens credibility.","example":"''Reliable same-day birthday cakes with delivery updates'' is clearer than ''the best bakery''.","heading":"Positioning is a specific promise"},{"body":"Reach and likes may indicate exposure, but track enquiries, orders, gross margin and repeat purchases to decide whether your positioning works.","example":"Test two headlines with comparable audiences and compare actual orders rather than just clicks.","heading":"Measure conversion, not vanity alone"}]'::jsonb,'[{"answer":"Segments group customers with similar needs or behaviour. Useful segments can be described, reached and served economically. Segment by urgency, context, needs and buying behaviour rather than demographics alone.","question":"How do you know a segment is useful?"},{"answer":"Good positioning states the difference that matters to a particular customer, supported by evidence. Trying to be the fastest, cheapest and highest quality to everyone weakens credibility.","question":"Why is a narrow positioning statement often stronger?"}]'::jsonb,'market','indigo',true)
