insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('opportunity-cost-decisions','Opportunity cost: the hidden price of every choice','economics','Economics','Beginner',8,'A practical introduction to scarcity, trade-offs and making decisions at the margin.',ARRAY['What is the next-best alternative in a decision?','Why should sunk costs usually not determine the next choice?']::text[],'[{"body":"Opportunity cost is the value of the next-best option you give up when choosing one alternative. It is not the sum of every alternative. Because time, money and attention are limited, even an apparently free activity has an opportunity cost.","example":"You spend two hours revising rather than earning KSh 600 at a part-time job. The forgone income is one possible measure of the opportunity cost.","heading":"Choices always exclude something"},{"body":"Money or time already spent and impossible to recover is sunk. Good decisions compare the extra benefits and costs that follow from this moment, not whether past spending feels wasted.","example":"After paying for a disappointing film, leaving early may be rational if the next hour could be used more productively.","heading":"Sunk costs are not future costs"},{"body":"Marginal benefit is the extra gain from one more unit of activity; marginal cost is its extra sacrifice. Continue while the expected additional benefit exceeds its additional cost.","example":"A fourth revision hour may be less useful than the first if your concentration is exhausted.","heading":"Think at the margin"}]'::jsonb,'[{"answer":"Opportunity cost is the value of the next-best option you give up when choosing one alternative. It is not the sum of every alternative. Because time, money and attention are limited, even an apparently free activity has an opportunity cost.","question":"What is the next-best alternative in a decision?"},{"answer":"Money or time already spent and impossible to recover is sunk. Good decisions compare the extra benefits and costs that follow from this moment, not whether past spending feels wasted.","question":"Why should sunk costs usually not determine the next choice?"}]'::jsonb,'chart','indigo',true)
