insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('semantic-html','Build accessible pages with semantic HTML','programming','Programming','Beginner',8,'Choose the right elements for navigation, headings, forms and actions.',ARRAY['Why should an action use a button rather than a clickable div?','How do semantic headings help navigation?']::text[],'[{"body":"Use header, main, nav, article and section when their meaning matches the content. Generic div containers have a place, but they provide less built-in structure for assistive technology.","example":"A learning page can contain one main region, an article for the lesson and a nav for chapter navigation.","heading":"HTML expresses purpose"},{"body":"Use a clear primary heading and descend into meaningful subsections. Heading levels should reflect document hierarchy rather than chosen font size.","example":"A course page may have an h1 for ''Accounting Basics'', h2 for ''Assets'' and h3 for ''Current assets''.","heading":"Headings create an outline"},{"body":"Buttons perform actions in the current context; links navigate to destinations. Input fields require associated labels; visual placeholder text is not a dependable substitute.","example":"Use a button for ''Check answer'' and an anchor for ''Next lesson''.","heading":"Buttons and links have distinct jobs"}]'::jsonb,'[{"answer":"Use header, main, nav, article and section when their meaning matches the content. Generic div containers have a place, but they provide less built-in structure for assistive technology.","question":"Why should an action use a button rather than a clickable div?"},{"answer":"Use a clear primary heading and descend into meaningful subsections. Heading levels should reflect document hierarchy rather than chosen font size.","question":"How do semantic headings help navigation?"}]'::jsonb,'code','indigo',true)
