insert into public.ace_lessons(slug,title,subject_slug,subject_label,level,reading_minutes,summary,learning_outcomes,sections,review_questions,illustration,accent,published) values ('supply-demand-market','How supply and demand shape a market','economics','Economics','Beginner',8,'Price, quantity, shortages and shifts explained with everyday examples.',ARRAY['What is the difference between a movement and a shift of demand?','What happens when supply decreases but demand is unchanged?']::text[],'[{"body":"Demand describes what consumers are willing and able to buy at various prices, assuming other conditions stay the same. A change in price moves along the demand curve. Changes in income or preferences shift the entire curve.","example":"When tea becomes cheaper, buyers may purchase more tea. When people develop a preference for tea, demand increases at every price.","heading":"Demand is a relationship"},{"body":"Supply describes what sellers are prepared to provide at various prices. Input costs, weather, technology and seller numbers can shift it.","example":"A drought reduces vegetable output even at unchanged prices: the supply curve shifts left.","heading":"Supply changes with conditions"},{"body":"At equilibrium, planned purchases equal planned sales. A shortage puts pressure on price to rise, while a surplus tends to put downward pressure on price.","example":"Sudden high demand for umbrellas during rain usually raises market price and quantity if sellers can expand supply.","heading":"Equilibrium is a balancing point"}]'::jsonb,'[{"answer":"Demand describes what consumers are willing and able to buy at various prices, assuming other conditions stay the same. A change in price moves along the demand curve. Changes in income or preferences shift the entire curve.","question":"What is the difference between a movement and a shift of demand?"},{"answer":"Supply describes what sellers are prepared to provide at various prices. Input costs, weather, technology and seller numbers can shift it.","question":"What happens when supply decreases but demand is unchanged?"}]'::jsonb,'chart','indigo',true)
